import { getAgent } from "@/lib/agents"
import { formatDisplayDate, toLocalDateString } from "@/lib/date"

import type { CommitInfo } from "../api"

interface TypedDayGroup<TCommit extends CommitInfo> {
  date: string
  displayDate: string
  commits: (TCommit & { _index: number })[]
}

function groupByDay<TCommit extends CommitInfo>(commits: TCommit[]): TypedDayGroup<TCommit>[] {
  const groups = new Map<string, TypedDayGroup<TCommit>>()
  commits.forEach((commit, index) => {
    const date = commit.commitDate ? toLocalDateString(commit.commitDate) : "unknown"
    let group = groups.get(date)
    if (!group) {
      group = {
        date,
        displayDate: date === "unknown" ? "Unknown Date" : formatDisplayDate(date),
        commits: [],
      }
      groups.set(date, group)
    }
    group.commits.push({ ...commit, _index: index })
  })
  return Array.from(groups.values())
}

export interface CommitListProps<TCommit extends CommitInfo = CommitInfo> {
  commits: TCommit[]
  org?: string
  repo?: string
  getCommitHref?: (commit: TCommit) => string
  renderCommitMeta?: (commit: TCommit) => ReactNode
  showAvatar?: boolean
}

export function CommitList<TCommit extends CommitInfo = CommitInfo>({
  commits,
  org,
  repo,
  getCommitHref,
  renderCommitMeta,
  showAvatar = true,
}: CommitListProps<TCommit>) {
  const dayGroups = groupByDay(commits)

  return (
    <ListView
      itemCount={commits.length}
      aria-label="Commits"
      className="@container overflow-hidden rounded border border-default bg-raised"
    >
      {dayGroups.map((group) => (
        <li
          key={group.date}
          role="presentation"
          className="list-none border-t border-default first:border-t-0"
        >
          <div className="flex h-12 items-center justify-between border-b border-default bg-subtle px-4">
            <span className="text-sm font-semibold text-default">{group.displayDate}</span>
            <span className="font-mono text-xs text-muted">
              {group.commits.length} commit{group.commits.length !== 1 ? "s" : ""}
            </span>
          </div>
          <ul role="presentation" className="m-0 list-none p-0">
            {group.commits.map((commit) => {
              const checkpoints = commit.checkpoints ?? []
              const checkpointCount = checkpoints.length
              const sessionCount = checkpoints.reduce(
                (total, checkpoint) => total + checkpoint.sessionCount,
                0,
              )
              const fileCount = commit.filesChanged ?? commit.fileStats?.length ?? 0
              const commitTitle = commit.commitMessage ?? "Untitled commit"
              const uniqueAgents = [
                ...new Set(checkpoints.flatMap((checkpoint) => checkpoint.agents)),
              ]
              const showUnknownAgentBadge = uniqueAgents.length === 0 && sessionCount > 0

              return (
                <ListViewItem
                  key={commit.commitSha}
                  index={commit._index}
                  href={
                    getCommitHref
                      ? getCommitHref(commit)
                      : `/gh/${encodeURIComponent(org ?? "")}/${encodeURIComponent(repo ?? "")}/commit/${encodeURIComponent(commit.commitSha)}`
                  }
                  className="flex flex-wrap items-center gap-x-2.5 gap-y-2 px-4 py-3 transition-colors hover:bg-hover md:h-12 md:flex-nowrap md:py-0"
                  aria-label={`${commitTitle}, ${commit.additions ?? 0} additions, ${commit.deletions ?? 0} deletions, ${fileCount} ${fileCount === 1 ? "file" : "files"}, ${checkpointCount} ${checkpointCount === 1 ? "checkpoint" : "checkpoints"}, by ${commit.commitAuthorUsername ?? "unknown author"}`}
                >
                  <span className="shrink-0 font-mono text-xs text-muted">
                    {commit.commitSha.slice(0, 7)}
                  </span>
                  <span
                    className={`min-w-0 truncate text-sm font-semibold ${checkpointCount > 0 ? "text-default" : "text-muted"}`}
                  >
                    {commitTitle}
                  </span>
                  {renderCommitMeta?.(commit)}
                  {uniqueAgents.length > 0 &&
                    uniqueAgents.map((agent) => {
                      const config = getAgent(agent)
                      return (
                        <Badge key={agent} className={`shrink-0 ${config.colorClass} agent-badge`}>
                          {config.label}
                        </Badge>
                      )
                    })}
                  {showUnknownAgentBadge && (
                    <Badge className={`shrink-0 ${getAgent(null).colorClass} agent-badge`}>
                      {getAgent(null).label}
                    </Badge>
                  )}
                  <span className="mt-1 flex basis-full items-center justify-start gap-4 font-mono text-xs text-muted md:mt-0 md:ml-auto md:shrink-0 md:basis-auto md:justify-start">
                    <LineCounts
                      additions={commit.additions ?? 0}
                      deletions={commit.deletions ?? 0}
                    />
                    <span>
                      {fileCount} {fileCount === 1 ? "file" : "files"}
                    </span>
                    {checkpointCount > 0 && (
                      <span>
                        {checkpointCount} checkpoint{checkpointCount === 1 ? "" : "s"}
                      </span>
                    )}
                    {showAvatar && (
                      <GitHubAvatar
                        username={commit.commitAuthorUsername ?? undefined}
                        className="size-5"
                      />
                    )}
                  </span>
                </ListViewItem>
              )
            })}
          </ul>
        </li>
      ))}
    </ListView>
  )
}

