// Shared types and utility functions for repo checkpoint sync
// Used by both repo-sync-service.ts and db-repos.ts to avoid circular dependencies

// Checkpoint data for upserting
export interface CheckpointData {
  checkpoint_id: string
  prompt: string | null
  agent: string | null
  steps: number | null
  session_count: number | null
  strategy: string | null
  branch: string | null
  session_id: string | null
  files_touched: string | null
  session_ids: string | null
  transcript_uuid_at_start: string | null
  transcript_lines_at_start: number | null
  checkpoint_transcript_start: number | null
  input_tokens: number | null
  cache_creation_tokens: number | null
  cache_read_tokens: number | null
  output_tokens: number | null
  api_call_count: number | null
  sessions: string | null
  created_at: string
}

// Commit data for upserting
export interface CommitData {
  checkpoint_id: string
  branch: string
  commit_sha: string
}

// Deduplicate checkpoints by checkpoint_id (keeps first occurrence)
// PostgreSQL doesn't allow duplicate keys in a single upsert batch
export function deduplicateCheckpoints<T extends { checkpoint_id: string }>(checkpoints: T[]): T[] {
  const seen = new Set<string>()
  return checkpoints.filter((cp) => {
    if (seen.has(cp.checkpoint_id)) return false
    seen.add(cp.checkpoint_id)
    return true
  })
}

// Deduplicate commits by checkpoint_id:branch composite key (keeps first occurrence)
// PostgreSQL doesn't allow duplicate keys in a single upsert batch
export function deduplicateCommits<T extends { checkpoint_id: string; branch: string }>(
  commits: T[],
): T[] {
  const seen = new Set<string>()
  return commits.filter((c) => {
    const key = `${c.checkpoint_id}:${c.branch}`
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
}

