// Maps DB checkpoint rows to API CheckpointInfo shape

import type { CheckpointInfo, SessionInfo } from "../types"
import { LEGACY_FALLBACK_AGENT_NAME } from "./constants"
import type { CheckpointWithCommit } from "./db/checkpoints"

/** Parse the sessions JSON column into SessionInfo[], falling back to the single agent field */
export function parseSessionsFromRow(row: CheckpointWithCommit): SessionInfo[] {
  if (row.sessions) {
    try {
      const parsed = (
        typeof row.sessions === "string" ? JSON.parse(row.sessions) : row.sessions
      ) as SessionInfo[]
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed
      }
    } catch {
      // Invalid JSON — fall through to default
    }
  }
  return [
    { prompt: row.prompt, agent: row.agent ?? LEGACY_FALLBACK_AGENT_NAME, steps: row.steps ?? 1 },
  ]
}

/** Map a DB checkpoint row to the API CheckpointInfo shape */
export function mapCheckpointToInfo(
  row: CheckpointWithCommit,
  checkpointRepoFullName: string | null = null,
): CheckpointInfo {
  const sessions = parseSessionsFromRow(row)
  const agents = [...new Set(sessions.map((s) => s.agent))]
  return {
    commitSha: row.commit_sha,
    commitMessage: row.commit_message,
    commitAuthor: row.commit_author,
    commitAuthorUsername: row.commit_author_username,
    commitDate: row.commit_date,
    additions: row.additions,
    deletions: row.deletions,
    filesChanged: row.files_changed,
    filesTouched: row.files_touched,
    fileStats: row.file_stats,
    checkpointId: row.checkpoint_id,
    createdAt: row.created_at ?? new Date().toISOString(),
    sessions,
    sessionCount: row.session_count ?? sessions.length,
    totalSteps: sessions.reduce((sum, s) => sum + (s.steps ?? 1), 0),
    agents,
    inputTokens: row.input_tokens,
    cacheCreationTokens: row.cache_creation_tokens,
    cacheReadTokens: row.cache_read_tokens,
    outputTokens: row.output_tokens,
    apiCallCount: row.api_call_count,
    attribution:
      row.attribution_calculated_at != null
        ? {
            calculatedAt: row.attribution_calculated_at,
            agentLines: row.attribution_agent_lines ?? 0,
            humanAdded: row.attribution_human_added ?? 0,
            humanModified: row.attribution_human_modified ?? 0,
            humanRemoved: row.attribution_human_removed ?? 0,
            totalCommitted: row.attribution_total_committed ?? 0,
            agentPercentage: row.attribution_agent_percentage ?? 0,
          }
        : null,
    checkpointRepoFullName,
  }
}

