export async function getCheckpointIdsWithMissingSessions(
  db: Kysely<DB>,
  repoId: string,
): Promise<string[]> {
  const rows = await db
    .selectFrom("repo_checkpoints")
    .select("checkpoint_id")
    .where("repo_id", "=", repoId)
    .where("sessions", "is", null)
    .execute()
  return rows.map((r) => r.checkpoint_id)
