    .where("rc.commit_author_github_id", "=", githubId)
    .where("rc.commit_date", ">=", new Date(startDate))
    .where("rc.commit_date", "<=", new Date(endDate))
    .orderBy("rc.commit_date", "desc")
    .limit(limit)
    .execute()

  if (commitRows.length === 0) return []

  const repoCommitPairs = commitRows.map(
    (row) => sql<boolean>`(cc.repo_id = ${row.repo_id} AND cc.commit_sha = ${row.commit_sha})`,
  )

  const checkpointRows = await db
    .selectFrom("repo_checkpoint_commits as cc")
    .leftJoin("repo_checkpoints as cp", (join) =>
      join
        .onRef("cp.repo_id", "=", "cc.repo_id")
        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
    )
    .select([
      "cc.repo_id",
      "cc.commit_sha",
      "cc.checkpoint_id",
      "cp.prompt",
      "cp.agent",
      "cp.session_count",
      "cp.sessions",
    ])
    .where((eb) => eb.or(repoCommitPairs))
    .execute()

  const checkpointsByRepoAndSha = new Map<string, Map<string, CheckpointListItem>>()
  for (const row of checkpointRows) {
    if (!row.commit_sha) continue

    let agents: string[] = []
    let totalSteps = 1
    let firstPrompt: string | null = row.prompt ?? null
    if (row.sessions) {
      try {
        const parsed = (
          typeof row.sessions === "string" ? JSON.parse(row.sessions) : row.sessions
        ) as { prompt?: string; agent: string; steps?: number }[]
        if (Array.isArray(parsed) && parsed.length > 0) {
          agents = [...new Set(parsed.map((session) => session.agent))]
          totalSteps = parsed.reduce((sum, session) => sum + (session.steps ?? 1), 0)
          firstPrompt = parsed[0]?.prompt ?? firstPrompt
        }
      } catch {
        // Invalid JSON - fall through
      }
    }

    if (agents.length === 0) {
      agents = [row.agent ?? LEGACY_FALLBACK_AGENT_NAME]
    }

    const key = `${row.repo_id}:${row.commit_sha}`
    const checkpointsForCommit =
      checkpointsByRepoAndSha.get(key) ?? new Map<string, CheckpointListItem>()
    if (!checkpointsForCommit.has(row.checkpoint_id)) {
      checkpointsForCommit.set(row.checkpoint_id, {
        checkpoint_id: row.checkpoint_id,
        prompt: firstPrompt,
        agent: row.agent ?? LEGACY_FALLBACK_AGENT_NAME,
        agents,
        session_count: row.session_count ?? 1,
        total_steps: totalSteps,
      })
    }
    checkpointsByRepoAndSha.set(key, checkpointsForCommit)
  }

  return commitRows.map((row) => ({
    commit_sha: row.commit_sha,
    commit_message: row.commit_message,
    commit_author_username: row.commit_author_username,
    commit_date: dateToStr(row.commit_date),
    additions: row.additions ?? 0,
    deletions: row.deletions ?? 0,
    files_changed: row.files_changed ?? 0,
    checkpoints: Array.from(
      checkpointsByRepoAndSha.get(`${row.repo_id}:${row.commit_sha}`)?.values() ?? [],
    ),
    repo_full_name: row.repo_full_name ?? "",
    is_private: toBool(row.is_private),
  }))
}

