    throw new Error("User has no GitHub token")
  }

  const now = Date.now()
  const expiresAt = user.github_token_expires_at
    ? new Date(user.github_token_expires_at).getTime()
    : null

  // Check if token is expired or about to expire
  const isExpired = expiresAt && now >= expiresAt - EXPIRATION_BUFFER_MS

  if (!isExpired) {
    // Token is still valid
    const token = await decrypt(user.github_token_enc, config.encryptionKey)
    return { token, refreshed: false }
  }

  // Token is expired - try to refresh
  if (!user.github_refresh_token_enc) {
    // No refresh token available - return current token and hope for the best
    // User will need to re-authenticate if it fails
    console.warn(`Token expired for user ${user.id} but no refresh token available`)
    const token = await decrypt(user.github_token_enc, config.encryptionKey)
    return { token, refreshed: false }
  }

