  }
}

// --- Installation Functions ---

/**
 * Upsert an installation record.
 * Creates a new installation or updates an existing one by github_installation_id.
 * Returns the installation ID.
 */
export async function upsertInstallation(
  db: Kysely<DB>,
  data: GitHubInstallationData,
): Promise<string> {
  // Check if installation already exists
  const existing = await db
    .selectFrom("installations")
    .select("id")
    .where("github_installation_id", "=", data.github_installation_id)
    .executeTakeFirst()

  const id = existing?.id ?? generateId()

  await db
    .insertInto("installations")
    .values({
      id,
      github_installation_id: data.github_installation_id,
      account_login: data.account_login,
      account_type: data.account_type,
      account_id: data.account_id,
      app_slug: data.app_slug ?? null,
      suspended_at: data.suspended_at ? new Date(data.suspended_at) : null,
    })
    .onDuplicateKeyUpdate({
      account_login: data.account_login,
      account_type: data.account_type,
      account_id: data.account_id,
      app_slug: data.app_slug ?? null,
      suspended_at: data.suspended_at ? new Date(data.suspended_at) : null,
    })
    .execute()

  return id
}

/**
 * Upsert multiple installation records.
 * Returns a map of github_installation_id -> installation id.
 */
export async function upsertInstallations(
  db: Kysely<DB>,
  installations: GitHubInstallationData[],
): Promise<Map<number, string>> {
  if (installations.length === 0) {
    return new Map()
  }

  const idMap = new Map<number, string>()

  for (const data of installations) {
    const id = await upsertInstallation(db, data)
    idMap.set(data.github_installation_id, id)
  }

  return idMap
}

