export async function createTestUser(
  db: Kysely<DB>,
  overrides: Partial<{
    id: string
    github_id: number
    github_login: string
    github_token_enc: string | null
    github_refresh_token_enc: string | null
    github_token_expires_at: Date | null
    discovery_enabled: number
    is_admin: number
    repos_synced_at: Date | null
    last_visited_at: Date | null
  }> = {},
) {
  const id = overrides.id ?? crypto.randomUUID()
  const values = {
    id,
    github_id: overrides.github_id ?? Math.floor(Math.random() * 1_000_000),
    github_login:
      overrides.github_login ?? `testuser-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    github_token_enc: overrides.github_token_enc ?? null,
    github_refresh_token_enc: overrides.github_refresh_token_enc ?? null,
    github_token_expires_at: overrides.github_token_expires_at ?? null,
    discovery_enabled: overrides.discovery_enabled ?? 0,
    is_admin: overrides.is_admin ?? 0,
    repos_synced_at: overrides.repos_synced_at ?? null,
    last_visited_at: overrides.last_visited_at ?? null,
  }

  await db.insertInto("users").values(values).execute()

  return db.selectFrom("users").selectAll().where("id", "=", id).executeTakeFirstOrThrow()
}

