import { useNavigate } from "@tanstack/react-router"
import { usePostHog } from "posthog-js/react"
import { useState, useEffect, useMemo, useCallback } from "react"

import { Badge, GitHubAvatar, Skeleton } from "@/components"
import { FilesSection } from "@/domains/platform/components/diff"
import { Page } from "@/domains/platform/components/Page"
import { ReauthenticateState } from "@/domains/platform/components/ReauthenticateState"
