import type { CheckpointInfo, CommitInfo } from "../api"
import { getCheckpointBreadcrumbs } from "../breadcrumbs"
import { CheckpointHeader } from "../components/CheckpointHeader"
import { CheckpointSidebar } from "../components/CheckpointSidebar"
import { SessionDetail } from "../components/SessionDetail"
import {
  useCheckpointsQuery,
  useCommitsQuery,
  useCheckpointTranscriptQuery,
  useResolveCheckpointQuery,
  useResolveCommitQuery,
} from "../hooks/useCommitsQuery"
import { useRepoBreadcrumbOptions } from "../hooks/useRepoBreadcrumbOptions"

/**
 * Scroll-based active item tracking (like blog TOC).
 * Tracks which element has most recently scrolled past a threshold (30% of viewport).
 * Returns a single active ID from a list of DOM element IDs.
 */
function useActiveItem(ids: string[]) {
  const [activeId, setActiveId] = useState<string>("")

  useEffect(() => {
    if (ids.length === 0) return

    const onScroll = () => {
      // At bottom of page, activate the last item
      if (window.innerHeight + window.scrollY >= document.body.scrollHeight - 2) {
        setActiveId(ids[ids.length - 1])
        return
      }
      const threshold = window.innerHeight * 0.3
      let current = ""
      for (const id of ids) {
        const el = document.getElementById(id)
        if (el && el.getBoundingClientRect().top <= threshold) {
          current = id
        }
      }
      setActiveId(current)
    }

    onScroll()
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [ids])

  return activeId
}

type DetailItem =
