  // This handles the case where the branch was deleted (e.g., after PR merge)
  const shouldResolve = !isLoading && !checkpoint && !matchedCommit && !checkpointsError
  const {
    data: resolveData,
    isLoading: isResolving,
    error: resolveError,
  } = useResolveCheckpointQuery(org, repo, checkpointId, branch, {
    enabled: shouldResolve,
