import { useQuery } from "@tanstack/react-query"

import {
  fetchRepoCommits,
  resolveCommit,
  fetchCheckpoints,
  fetchCheckpointStatus,
  fetchBranches,
  fetchCheckpointTranscript,
  resolveCheckpoint,
  searchCheckpoints,
  type CommitInfo,
  type RepoCommitsResponse,
  type CheckpointInfo,
  type SessionInfo,
  type CheckpointsResponse,
  type CheckpointStatusResponse,
  type ResolveCommitResponse,
  type BranchesResponse,
  type TranscriptMessage,
  type SessionTranscript,
  type CheckpointTranscriptResponse,
  type CheckpointResolveResponse,
  type SearchCheckpointsResponse,
  type ToolCall,
  type ToolCallResult,
} from "../api"

export type {
  CommitInfo,
  CheckpointInfo,
  SessionInfo,
  TranscriptMessage,
  SessionTranscript,
  CheckpointTranscriptResponse,
  ToolCall,
  ToolCallResult,
}

export function useCommitsQuery(org: string, repo: string, branch: string = "main") {
  return useQuery<RepoCommitsResponse>({
    queryKey: ["github", "commits", org, repo, branch],
    queryFn: () => fetchRepoCommits(org, repo, branch),
    staleTime: 5 * 60 * 1000, // 5 minutes
  })
}

export function useCheckpointStatusQuery(org: string, repo: string) {
  return useQuery<CheckpointStatusResponse>({
    queryKey: ["github", "checkpoint-status", org, repo],
    queryFn: () => fetchCheckpointStatus(org, repo),
    staleTime: 5 * 60 * 1000, // 5 minutes
  })
}

export function useResolveCommitQuery(
  org: string,
  repo: string,
  commitSha: string,
  options?: { enabled?: boolean },
) {
  return useQuery<ResolveCommitResponse>({
    queryKey: ["github", "commit-resolve", org, repo, commitSha],
    queryFn: () => resolveCommit(org, repo, commitSha),
    enabled: options?.enabled ?? true,
  })
}

export function useCheckpointsQuery(org: string, repo: string, branch: string = "main") {
  return useQuery<CheckpointsResponse>({
    queryKey: ["github", "checkpoints", org, repo, branch],
    queryFn: () => fetchCheckpoints(org, repo, branch),
    staleTime: 5 * 60 * 1000, // 5 minutes
  })
}

export function useBranchesQuery(org: string, repo: string) {
  return useQuery<BranchesResponse>({
    queryKey: ["github", "branches", org, repo],
    queryFn: () => fetchBranches(org, repo),
    staleTime: 10 * 60 * 1000, // 10 minutes
  })
}

export function useCheckpointTranscriptQuery(
  org: string,
  repo: string,
  checkpointId: string,
  options?: { enabled?: boolean },
) {
  return useQuery<CheckpointTranscriptResponse>({
    queryKey: ["github", "checkpoint-transcript", org, repo, checkpointId],
    queryFn: () => fetchCheckpointTranscript(org, repo, checkpointId),
    enabled: options?.enabled ?? true,
  })
}

// Resolve a checkpoint by ID - finds which branches it exists on
// Used when the requested branch is deleted (e.g., after PR merge)
export function useResolveCheckpointQuery(
  org: string,
  repo: string,
  checkpointId: string,
  requestedBranch?: string,
  options?: { enabled?: boolean },
) {
  return useQuery<CheckpointResolveResponse>({
    queryKey: ["github", "checkpoint-resolve", org, repo, checkpointId, requestedBranch],
    queryFn: () => resolveCheckpoint(org, repo, checkpointId, requestedBranch),
    enabled: options?.enabled ?? true,
    staleTime: 5 * 60 * 1000, // 5 minutes
  })
}

export function useSearchCheckpointsQuery(
  org: string,
  repo: string,
  query: string,
  branch: string,
) {
  return useQuery<SearchCheckpointsResponse>({
    queryKey: ["github", "checkpoints-search", org, repo, query, branch],
    queryFn: () => searchCheckpoints(org, repo, query, branch),
    enabled: query.trim().length > 0,
    staleTime: 30_000,
    placeholderData: (prev) => prev, // keep previous results while fetching
  })
}

export type { CheckpointResolveResponse }

