function isExternalCheckpointRepo(
  codeRepoFullName: string,
  checkpointRepoFullName: string,
): boolean {
  return checkpointRepoFullName !== codeRepoFullName
}

function shouldRetryCheckpointFetchWithUserToken(
  checkpointIds: string[],
  result: BatchResult<SessionData>,
): boolean {
  if (checkpointIds.length === 0 || result.failedItems.length !== checkpointIds.length) {
    return false
  }

  const combinedErrors = result.errors.join(" ").toLowerCase()
  return (
    combinedErrors.includes("resource not accessible") ||
    combinedErrors.includes("could not resolve to a repository")
  )
}

async function fetchSessionDataWithCheckpointRepoFallback(params: {
  codeRepoFullName: string
  checkpointRepoFullName: string
  checkpointIds: string[]
  installationId: number
  db: Db
  env: Env
  appToken: string | null
  metricContext: Record<string, string | number | boolean | null | undefined>
}): Promise<BatchResult<SessionData> | null> {
  const {
    codeRepoFullName,
    checkpointRepoFullName,
    checkpointIds,
    installationId,
    db,
    env,
    appToken,
    metricContext,
  } = params

  if (checkpointIds.length === 0) {
    return {
      data: new Map(),
      failedItems: [],
      errors: [],
    }
  }

  let appResult: BatchResult<SessionData> | null = null
  if (appToken) {
    appResult = await fetchSessionDataBatch(checkpointRepoFullName, checkpointIds, appToken)
    if (
      !isExternalCheckpointRepo(codeRepoFullName, checkpointRepoFullName) ||
      !shouldRetryCheckpointFetchWithUserToken(checkpointIds, appResult)
    ) {
      return appResult
    }

    logCheckpointMetric("checkpoint_repo_user_token_fallback", {
      ...metricContext,
      reason: "app_token_repo_access_failed",
      checkpointRepo: checkpointRepoFullName,
      checkpointCount: checkpointIds.length,
    })
  } else if (!isExternalCheckpointRepo(codeRepoFullName, checkpointRepoFullName)) {
    return null
  } else {
    logCheckpointMetric("checkpoint_repo_user_token_fallback", {
      ...metricContext,
      reason: "app_token_unavailable",
      checkpointRepo: checkpointRepoFullName,
      checkpointCount: checkpointIds.length,
    })
  }

  const installationUsers = await db.installations.findUsersByGitHubId(installationId)

  for (const user of installationUsers) {
    if (!user.github_token_enc) {
      continue
    }

    try {
      const tokenResult = await getValidGitHubToken(
        db,
        user,
        {
          clientId: env.GITHUB_CLIENT_ID,
          clientSecret: env.GITHUB_CLIENT_SECRET,
          encryptionKey: env.ENCRYPTION_KEY,
        },
        env.ENTIRE_CACHE,
      )
      const userResult = await fetchSessionDataBatch(
        checkpointRepoFullName,
        checkpointIds,
        tokenResult.token,
      )

      if (!shouldRetryCheckpointFetchWithUserToken(checkpointIds, userResult)) {
        logCheckpointMetric("checkpoint_repo_user_token_fallback_success", {
          ...metricContext,
          checkpointRepo: checkpointRepoFullName,
          userId: user.id,
          refreshed: tokenResult.refreshed,
        })
        return userResult
      }
    } catch (err) {
      logCheckpointMetric("checkpoint_repo_user_token_fallback_error", {
        ...metricContext,
        checkpointRepo: checkpointRepoFullName,
        userId: user.id,
        error: err instanceof Error ? err.message : String(err),
      })
    }
  }

  if (appResult) {
    return appResult
  }

  logCheckpointMetric("checkpoint_repo_user_token_fallback_unavailable", {
    ...metricContext,
    checkpointRepo: checkpointRepoFullName,
    checkpointCount: checkpointIds.length,
  })
  return null
}

