export interface RepoSyncMessage {
  repoId: string
  reason: "installation" | "reconciliation" | "manual" | "user_sync"
  priority: number // 10 = immediate (installation, user_sync), 5 = manual, 1 = reconciliation
  queuedAt: string
  task?:
    | "sync_recent"
    | "sync_branch_history"
    | "checkpoint_sync"
    | "fastlane_sync"
    | "branch_commit_backfill" // last three are legacy aliases
  branch?: string // for history sync (single branch)
  branches?: string[] // for recent sync (multiple branches)
}

